// University of Seoul, Seoul campus (서울시립대학교 서울캠퍼스, 서울 동대문구 전농동). Data is generated by scripts/campuses/uos/build-package.mjs
// from the pilot (pilot/uos-seoul-v2): every model of active-models.json (100주년기념관·중앙도서관·경농관·대학본부 detailed, 정문·시대탑 custom,
// the rest generic), all destructible (no hospital, religious or hanok heritage building - 경농관·박물관·자작마루 are registered heritage
// university buildings and break, rule 10.1: the protected list is empty), a baked ground drawn with the pilot's ground shader (the SKKU
// port src/campuses/skku/ground-look.js; the pilot's final-materials.js is the same shader as dankook's), the preview's own planting (same
// trees), the place models (하늘못·노천극장, 자주터, 선벽원, 도서관 대계단, 동문탑) + landscape/*.gltf and the non-destructible context
// (전농동, 청량리, 배봉산) fading into the haze. Local only until the user approves (registry public: false).
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, UOS_PLACEMENTS, UOS_BUILDING_BASE, UOS_HEIGHT_GRIDS, UOS_HEIGHT_RANGE_M, UOS_ENV_IDS, UOS_ENV_MANIFEST_IDS, UOS_LOOK, UOS_ZONES, UOS_DISPLAY, UOS_PROVENANCE } from './data.js';
import { UOS_FOOTPRINTS } from './footprints.js';
import { UOS_PROTECTED } from './protected.js';
import { createSkkuGroundLook } from '../skku/ground-look.js';

const MODEL_IDS = Object.freeze(UOS_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/uos/${file}`, import.meta.url).href;
const HAZE = UOS_DISPLAY.haze, FADE = UOS_DISPLAY.fade;

export const UOS = Object.freeze({
  id: 'uos',
  meta: Object.freeze({ school: '서울시립대학교', campus: '서울캠퍼스', short: '시립대', modelNoun: '시립대' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: UOS_PLACEMENTS,
  approvedCount: UOS_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: Object.freeze(['centennial', 'mainGate', 'mainAdmin', 'library', 'gyeongnong'].filter(id => MODEL_IDS.includes(id))),
  startBuildingId: 'centennial',
  // Start: from over the 정문·시대탑 / 100주년기념관 side (west, 서울시립대로) looking east along the gate -> 자주터 axis: 시대탑 and
  // 100주년기념관 in front, 조형관·미래관 and 경농관·박물관 on either side, 자주터 and 대학본부 behind, 배봉산 at the far end.
  // Box in world units (metres x 0.5, z = -N): E -324..-200 m, N -44..44 m (gate tower to 100주년기념관 / 조형관 / 전농관), 0..14 m high;
  // azimuth -1.42 = camera west, a little south, along the gate -> 자주터 axis. Projected in Node with src/camera.js before any browser run
  // (W1 2026-10-22): camera at E -435 / N -26 m, 87 m up (1280x800; 182 m up at 390x844); campus buildings' share of the HUD-free band
  // 0.53 (1280) / 0.37 (390); the band's top corners meet the ground at E 43..134 m (inside the campus), the bottom corners at the gate
  // (E -346..-324 m), so the campus fills the band and the 전농동 / 청량리 context only shows above it. Phone: 100주년기념관 at the left edge.
  view: Object.freeze({ startFrame: Object.freeze({ min: Object.freeze([-162, -1.5, -22]), max: Object.freeze([-100, 7, 22]), azimuth: -1.42 }) }),
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: UOS_ENV_MANIFEST_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: UOS_HEIGHT_GRIDS, buildingBase: UOS_BUILDING_BASE,
    source: 'Relative terrain estimate (Copernicus GLO-30, building-filled, canopy lowered by an estimate + floor-link / photo level evidence, pilot/uos-seoul-v2); not a survey' }),
  environment: Object.freeze({ provenance: UOS_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, planting and the place models estimated' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: UOS_ENV_IDS, castShadow: Object.freeze([]), materialHook: createSkkuGroundLook(UOS_LOOK, UOS_ZONES),
      // context.json display fade (preview.js FADE): campus clear to r0, the backdrop melts into the haze by r1
      fade: Object.freeze({ centre_m: Object.freeze([...FADE.centreEN]), near_m: FADE.r0_m, far_m: FADE.r1_m, ...(FADE.linearShare ? { linear: FADE.linearShare } : {}), colour: HAZE }), playMargin_m: 30,
      source: 'pilot/uos-seoul-v2 preview ground + planting + landscape + context, baked' }),
  }),
  // Protected: none at UOS (every model destructible). Kept so a later decision only needs a rebuild; the manifest exists only when the
  // list is not empty (src/main.js loads protected models only when models.length > 0).
  protected: Object.freeze({
    ...(UOS_PROTECTED.length ? { manifestURL: asset('protected/manifest.json') } : {}),
    models: UOS_PROTECTED,
  }),
  // Hazard tape around every destructible building (src/engine/hazard-tape.js): none on the context.
  hazardTape: Object.freeze({ footprints: UOS_FOOTPRINTS }),
  scene: Object.freeze({
    // preview.js: hemisphere (#fff, #7d8a78, 1.35), sun #fff4e2 3.1 from (-220, 340, 280) to (0, 10, 0) -> halved; fog as dankook (same pipeline)
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 700, far: 2200 }),
    hemisphere: Object.freeze({ sky: '#ffffff', ground: '#7d8a78', intensity: 1.35 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 3.1, position: Object.freeze([-110, 170, 140]), shadowSpan: 260 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: UOS_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default UOS;
